#!/bin/bash
# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
DATE_ARG=${1:-}; DATE_ARG=${DATE_ARG////-}
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="$DATE_ARG" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

[ "$(BOOKINGS=$t bash src/list.sh 2026/01/02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by slash date"; fail=1; }
rm -f "$t"; exit $fail

all specs pass

